CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE libraries(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), description TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE words(id TEXT PRIMARY KEY NOT NULL, kanji TEXT, kana TEXT NOT NULL CHECK(length(trim(kana))>0), jlpt TEXT CHECK(jlpt IN ('N1','N2','N3','N4','N5')), note TEXT NOT NULL DEFAULT '', note_format TEXT NOT NULL DEFAULT 'plain' CHECK(note_format IN ('plain','markdown')), search_text TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE senses(id TEXT PRIMARY KEY NOT NULL, word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, position INTEGER NOT NULL CHECK(position>=0), meaning TEXT NOT NULL CHECK(length(trim(meaning))>0), UNIQUE(word_id,position), UNIQUE(word_id,id));
CREATE TABLE word_pos(word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, pos_code TEXT NOT NULL CHECK(pos_code IN ('noun','godan_verb','ichidan_verb','suru_verb','kuru_verb','i_adjective','na_adjective','adverb','particle','expression','other')), PRIMARY KEY(word_id,pos_code));
CREATE TABLE examples(id TEXT PRIMARY KEY NOT NULL, word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, sense_id TEXT, position INTEGER NOT NULL CHECK(position>=0), jp TEXT NOT NULL CHECK(length(trim(jp))>0), cn TEXT, UNIQUE(word_id,position), FOREIGN KEY(word_id,sense_id) REFERENCES senses(word_id,id) ON DELETE CASCADE);
CREATE TABLE pitch_accents(id TEXT PRIMARY KEY NOT NULL, word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, mora_count INTEGER NOT NULL CHECK(mora_count>0), downstep INTEGER NOT NULL CHECK(downstep>=0 AND downstep<=mora_count), source TEXT);
CREATE TABLE library_words(library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE, word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, added_at INTEGER NOT NULL, PRIMARY KEY(library_id,word_id));
CREATE TABLE tags(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL UNIQUE CHECK(length(trim(name))>0));
CREATE TABLE word_tags(word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(word_id,tag_id));
CREATE TABLE media(id TEXT PRIMARY KEY NOT NULL, sha256 TEXT NOT NULL UNIQUE CHECK(length(sha256)=64), relative_path TEXT NOT NULL UNIQUE CHECK(length(relative_path)>0 AND relative_path NOT LIKE '/%' AND relative_path NOT LIKE '%..%' AND instr(relative_path,':')=0 AND instr(relative_path,char(92))=0), mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), status TEXT NOT NULL CHECK(status IN ('staged','ready')));
CREATE TABLE word_media(word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, media_id TEXT NOT NULL REFERENCES media(id), role TEXT NOT NULL CHECK(role IN ('pronunciation','image')), position INTEGER NOT NULL CHECK(position>=0), PRIMARY KEY(word_id,role,position));
CREATE TABLE source_links(source_namespace TEXT NOT NULL, external_id TEXT NOT NULL, word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, last_import_hash TEXT NOT NULL, PRIMARY KEY(source_namespace,external_id));
CREATE TABLE scheduler_parameters(id TEXT PRIMARY KEY NOT NULL, algorithm TEXT NOT NULL, version TEXT NOT NULL, parameters_json TEXT NOT NULL CHECK(json_valid(parameters_json)), desired_retention REAL NOT NULL CHECK(desired_retention BETWEEN 0.80 AND 0.97), created_at INTEGER NOT NULL);
CREATE TABLE cards(id TEXT PRIMARY KEY NOT NULL, word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE, card_type TEXT NOT NULL CHECK(card_type='recognition'), state TEXT NOT NULL CHECK(state IN ('new','learning','review','relearning')), due_at INTEGER, last_review_at INTEGER, stability REAL CHECK(stability>0), difficulty REAL CHECK(difficulty BETWEEN 1 AND 10), reps INTEGER NOT NULL DEFAULT 0 CHECK(reps>=0), lapses INTEGER NOT NULL DEFAULT 0 CHECK(lapses>=0), learning_step INTEGER CHECK(learning_step>=0), suspended INTEGER NOT NULL DEFAULT 0 CHECK(suspended IN (0,1)), buried_until INTEGER, scheduler_version TEXT NOT NULL, parameter_set_id TEXT NOT NULL REFERENCES scheduler_parameters(id), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), introduced_at INTEGER, eligible_since INTEGER NOT NULL, UNIQUE(word_id,card_type));
CREATE TABLE sessions(id TEXT PRIMARY KEY NOT NULL, scope_json TEXT NOT NULL CHECK(json_valid(scope_json)), started_at INTEGER NOT NULL, finished_at INTEGER, status TEXT NOT NULL CHECK(status IN ('active','completed','abandoned')), timezone TEXT NOT NULL, day_start_hour INTEGER NOT NULL CHECK(day_start_hour BETWEEN 0 AND 6));
CREATE TABLE review_events(id TEXT PRIMARY KEY NOT NULL, card_id TEXT NOT NULL REFERENCES cards(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES sessions(id), event_type TEXT NOT NULL CHECK(event_type IN ('rating','reset')), rating INTEGER, reviewed_at INTEGER NOT NULL, study_day TEXT NOT NULL, elapsed_ms INTEGER NOT NULL CHECK(elapsed_ms BETWEEN 0 AND 120000), before_json TEXT NOT NULL CHECK(json_valid(before_json)), after_json TEXT NOT NULL CHECK(json_valid(after_json)), scheduler_version TEXT NOT NULL, parameter_set_id TEXT NOT NULL REFERENCES scheduler_parameters(id), reverted_at INTEGER, is_new_introduction INTEGER NOT NULL DEFAULT 0 CHECK(is_new_introduction IN (0,1)), CHECK((event_type='rating' AND rating IS NOT NULL AND rating BETWEEN 1 AND 4) OR (event_type='reset' AND rating IS NULL)));
CREATE TABLE import_jobs(id TEXT PRIMARY KEY NOT NULL, file_hash TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ('csv','json','xlsx','jword')), status TEXT NOT NULL CHECK(status IN ('staging','validated','committed','cancelled','failed')), summary_json TEXT NOT NULL CHECK(json_valid(summary_json)), created_at INTEGER NOT NULL, committed_at INTEGER);
CREATE TABLE settings(key TEXT PRIMARY KEY NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0));
CREATE INDEX words_updated ON words(updated_at DESC,id);
CREATE INDEX memberships_word ON library_words(word_id,library_id);
CREATE INDEX tags_word ON word_tags(tag_id,word_id);
CREATE INDEX senses_word ON senses(word_id);
CREATE INDEX examples_word ON examples(word_id);
CREATE INDEX pitch_word ON pitch_accents(word_id);
CREATE INDEX source_word ON source_links(word_id);
CREATE INDEX media_reference ON word_media(media_id);
CREATE INDEX cards_due ON cards(suspended,due_at,id);
CREATE INDEX reviews_card ON review_events(card_id,reviewed_at);
CREATE INDEX reviews_day ON review_events(study_day,reverted_at);
